              "日本年金機構 診断書(精神の障害用)様式の記入上の注意(日常生活能力の判定は単身生活を前提に評価)・確認日 2026-09-03",
              "厚生労働省「障害年金受給者実態調査」令和6年度・当サイト裁決事例集(91件)・確認日 2026-09-02"
