            "type": "ul",
            "items": [
              "厚生労働省「障害年金受給者実態調査」令和6年度(新規裁定 146,225件、精神 70.3%、等級分布、不支給割合、再認定の継続)・確認日 2026-09-02",
              "厚生労働省「国民年金・厚生年金保険 障害認定基準」第8節 精神の障害・確認日 2026-09-03"
            ]
